    for name in GLOBAL_NAMES {
        b.global(name);
    }
    for &(id, name, parent, sprite, mask, solid, visible, persistent, depth) in OBJECTS {
        let info = ObjectInfo {
            name: name.into(),
            parent: u32::try_from(parent).ok().map(ObjectId),
            sprite,
            mask,
            solid,
            visible,
            persistent,
            depth,
        };
        b.object(ObjectId(id), info);
    }
    for &(id, event, f) in EVENTS {
        b.event(ObjectId(id), event, f);
    }
    for &(id, vars) in LAYOUTS {
        b.layout(ObjectId(id), vars);
    }
    // The collision stage is gm's default, GM8's (`World::run_collisions`).
    b.build()
